/**
 * ฟังก์ชันค้นหา Applicator ตาม App No หรือ Terminal Name
 */
export function searchApplicators(query: string, limit = 15): ApplicatorItem[] {
  if (!query || query.trim().length === 0) return APPLICATOR_MASTER.slice(0, limit);
  const q = query.trim().toLowerCase();
  const cleanQ = q.replace(/^tw-?/i, '');

  return APPLICATOR_MASTER.filter(item => {
    const appMatch = item.appNo.toLowerCase().includes(q) || (item.rawNo && item.rawNo.toLowerCase().includes(cleanQ));
    const termMatch = item.terminalName.toLowerCase().includes(q);
    const itemAppMatch = item.itemApp?.toLowerCase().includes(q);
    return appMatch || termMatch || itemAppMatch;
  }).slice(0, limit);
}
